<?php require_once '../config.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';if(in_array($status,['pending','approved','fulfilled'],true)){db()->prepare('UPDATE reward_redemptions SET status=? WHERE id=?')->execute([$status,$id]);flash('Reward request updated.');}else flash('Invalid status.','error');redirect('reward_requests.php');}
$rows=db()->query('SELECT rr.id,rr.points_spent,rr.status,rr.created_at,c.name,c.email,r.name AS reward_name FROM reward_redemptions rr JOIN customers c ON c.id=rr.customer_id JOIN rewards r ON r.id=rr.reward_id ORDER BY rr.id DESC')->fetchAll();page_start('Reward requests');?><section class="panel"><p>Review customer reward requests and update fulfilment status after handling the physical reward.</p><div class="table-wrap"><table><tr><th>Customer</th><th>Email</th><th>Reward</th><th>Points</th><th>Requested</th><th>Status</th><th>Update</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['reward_name'])?></td><td><?=e($r['points_spent'])?></td><td><?=e($r['created_at'])?></td><td><?=e($r['status'])?></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($r['id'])?>"><select name="status"><option value="pending" <?=$r['status']==='pending'?'selected':''?>>Pending</option><option value="approved" <?=$r['status']==='approved'?'selected':''?>>Approved</option><option value="fulfilled" <?=$r['status']==='fulfilled'?'selected':''?>>Fulfilled</option></select><button class="btn small">Save</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7">No reward requests yet.</td></tr><?php endif;?></table></div></section><?php page_end();?>
